package com.rescuefarm.ui.engagement;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.fragment.app.Fragment;import androidx.lifecycle.ViewModelProvider;import com.google.firebase.auth.FirebaseAuth;import com.rescuefarm.R;import com.rescuefarm.domain.enums.ReportTargetType;
public class ReportFragment extends Fragment{public @Nullable View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup p,@Nullable Bundle s){return i.inflate(R.layout.fragment_report,p,false);}@Override public void onViewCreated(@NonNull View v,@Nullable Bundle s){android.widget.Button history=new android.widget.Button(requireContext());history.setText("Báo cáo của tôi");history.setOnClickListener(x->androidx.navigation.fragment.NavHostFragment.findNavController(this).navigate(R.id.reportResultFragment));((android.widget.LinearLayout)v.findViewById(R.id.submitReportButton).getParent()).addView(history);Spinner type=v.findViewById(R.id.reportTargetType);EditText id=v.findViewById(R.id.reportTargetId),reason=v.findViewById(R.id.reportReason),description=v.findViewById(R.id.reportDescription);type.setAdapter(new ArrayAdapter<>(requireContext(),android.R.layout.simple_spinner_dropdown_item,ReportTargetType.values()));Bundle a=getArguments();if(a!=null){id.setText(a.getString("targetId",""));try{type.setSelection(ReportTargetType.valueOf(a.getString("targetType","PRODUCT")).ordinal());}catch(Exception ignored){}}EngagementViewModel vm=new ViewModelProvider(this,new EngagementViewModelFactory(requireContext())).get(EngagementViewModel.class);vm.getState().observe(getViewLifecycleOwner(),x->{if(x.getStatus()==EngagementState.Status.ERROR||x.getStatus()==EngagementState.Status.SUCCESS)Toast.makeText(requireContext(),x.getMessage(),Toast.LENGTH_LONG).show();});v.findViewById(R.id.submitReportButton).setOnClickListener(x->{String uid=FirebaseAuth.getInstance().getCurrentUser()==null?"":FirebaseAuth.getInstance().getCurrentUser().getUid();vm.report(uid,(ReportTargetType)type.getSelectedItem(),id.getText().toString().trim(),reason.getText().toString().trim(),description.getText().toString().trim());});}}
